import React, { useContext, useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { CartContext } from "../context/CartContext";
import { toast, ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import {
  FaShoppingCart,
  FaHome,
  FaProductHunt,
  FaArrowLeft,
  FaBars,
} from "react-icons/fa";
import axios from "axios";

// ✅ Base64 Background Image Component
function Base64Background({ filename }) {
  const [img, setImg] = useState(null);

  useEffect(() => {
    axios
      .get(`https://techgadgetsstore-backend.onrender.com/api/image-base64/${filename}`)
      .then((res) => setImg(res.data.image))
      .catch((err) => console.error("Image load error:", err));
  }, [filename]);

  return img ? (
    <img
      src={img}
      alt="Background"
      className="absolute inset-0 w-full h-full object-cover z-0"
    />
  ) : null;
}

// ✅ Base64 Image Component
function Base64Image({ filename, alt, className }) {
  const [img, setImg] = useState(null);

  useEffect(() => {
    if (!filename) return; // avoid crash if no image
    axios
      .get(`https://techgadgetsstore-backend.onrender.com/api/image-base64/${filename}`)
      .then((res) => setImg(res.data.image))
      .catch((err) => console.error("Image load error:", err));
  }, [filename]);

  return img ? (
    <img src={img} alt={alt || "Product"} className={className} />
  ) : (
    <div className="w-48 h-48 bg-gray-100 flex items-center justify-center">
      Loading...
    </div>
  );
}

function CartPage() {
  const { cartItems, removeFromCart, clearCart } = useContext(CartContext);
  const [isCartRestored, setIsCartRestored] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const navigate = useNavigate();

  // ✅ show "cart restored" message
  useEffect(() => {
    if (cartItems.length > 0) {
      setIsCartRestored(true);
      setTimeout(() => setIsCartRestored(false), 3000);
    }
  }, [cartItems.length]);

  // ✅ safe total price calculation
  const totalPrice = cartItems.reduce(
    (sum, item) =>
      sum + ((item?.product?.price || 0) * (item?.quantity || 0)),
    0
  );

  const handleBuyNow = (item) => {
    if (!item?.product) return;
    navigate("/buy-now", {
      state: { product: item.product, quantity: item.quantity || 1 },
    });
  };

  const handleBuyAll = () => {
    if (cartItems.length === 0) {
      toast.info("Your cart is empty. Add products to proceed.");
      return;
    }

    navigate("/buy-now", {
      state: {
        cartDetails: cartItems.map((item) => ({
          product: item?.product,
          quantity: item?.quantity || 1,
        })),
        totalPrice,
      },
    });
  };

  return (
    <div className="relative font-sans min-h-screen flex flex-col overflow-hidden">
      {/* ✅ Background */}
      <Base64Background filename="bgimage.jpg" />

      <ToastContainer />

      {/* ✅ Navbar */}
      <nav className="bg-pink-600 text-white py-4 px-6 shadow-lg fixed top-0 left-0 w-full z-50">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button
              className="text-xl hover:text-gray-200"
              onClick={() => navigate(-1)}
            >
              <FaArrowLeft />
            </button>
            <h1 className="text-2xl font-extrabold tracking-wide">
              Tech Gadgets Store
            </h1>
          </div>
          <div className="md:hidden">
            <button onClick={() => setMenuOpen(!menuOpen)}>
              <FaBars className="text-2xl" />
            </button>
          </div>
          <div className="hidden md:flex space-x-6">
            <button
              onClick={() => navigate("/")}
              className="flex items-center gap-2 text-lg hover:text-gray-200"
            >
              <FaHome /> Home
            </button>
            <button
              onClick={() => navigate("/products")}
              className="flex items-center gap-2 text-lg hover:text-gray-200"
            >
              <FaProductHunt /> Products
            </button>
            <button
              onClick={() => navigate("/cart")}
              className="flex items-center gap-2 text-lg hover:text-gray-200"
            >
              <FaShoppingCart /> Cart
            </button>
          </div>
        </div>

        {/* ✅ Mobile Menu */}
        {menuOpen && (
          <div className="md:hidden mt-4 flex flex-col gap-3">
            <button
              onClick={() => navigate("/")}
              className="flex items-center gap-2 text-lg hover:text-gray-200"
            >
              <FaHome /> Home
            </button>
            <button
              onClick={() => navigate("/products")}
              className="flex items-center gap-2 text-lg hover:text-gray-200"
            >
              <FaProductHunt /> Products
            </button>
            <button
              onClick={() => navigate("/cart")}
              className="flex items-center gap-2 text-lg hover:text-gray-200"
            >
              <FaShoppingCart /> Cart
            </button>
          </div>
        )}
      </nav>

      {/* ✅ Cart Section */}
      <div className="container mx-auto px-4 pt-28">
        {isCartRestored && (
          <div className="bg-green-500 text-white text-center py-3 rounded-lg mb-4 animate-bounce">
            Cart restored successfully!
          </div>
        )}

        <h1 className="text-4xl font-extrabold text-center text-gray-800 mb-8 drop-shadow-lg">
          My Cart 🛒
        </h1>

        {cartItems.length === 0 ? (
          <p className="text-center text-gray-500 text-lg">
            Your cart is empty. Start adding some products!
          </p>
        ) : (
          <div className="bg-white shadow-2xl rounded-2xl p-8">
            <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
              {cartItems.map((item, index) => (
                <div
                  key={index}
                  className="flex flex-col items-center border border-gray-200 rounded-lg p-4 gap-4 shadow-lg transform hover:scale-105 transition-transform duration-300"
                >
                  <Base64Image
                    filename={item?.product?.image_url}
                    alt={item?.product?.name || "Product"}
                    className="w-48 h-48 object-cover rounded-xl"
                  />
                  <div className="text-center">
                    <h2 className="text-xl font-bold text-gray-800">
                      {item?.product?.name || "Unknown Product"}
                    </h2>
                    <p className="text-gray-600 mt-2">
                      Quantity: <strong>{item?.quantity || 0}</strong>
                    </p>
                    <p className="text-pink-700 font-bold mt-1">
                      Price: ₹{(item?.product?.price || 0) * (item?.quantity || 0)}
                    </p>
                  </div>
                  <div className="flex flex-col gap-2">
                    <button
                      onClick={() => handleBuyNow(item)}
                      className="bg-green-500 text-white py-2 px-4 rounded-lg hover:bg-green-600"
                    >
                      Buy Now
                    </button>
                    <button
                      onClick={() => removeFromCart(item?.product?.id)}
                      className="bg-red-500 text-white py-2 px-4 rounded-lg hover:bg-red-600"
                    >
                      Remove
                    </button>
                  </div>
                </div>
              ))}
            </div>

            <div className="text-right text-2xl font-semibold text-gray-800 mt-6">
              Total Price: <span className="text-pink-700">₹{totalPrice}</span>
            </div>

            <div className="flex justify-between mt-6">
              <button
                onClick={handleBuyAll}
                className="bg-pink-600 text-white py-3 px-8 rounded-lg hover:bg-pink-500 shadow-lg"
              >
                Buy All
              </button>
              <button
                onClick={clearCart}
                className="bg-gray-700 text-white py-3 px-8 rounded-lg hover:bg-gray-600 shadow-lg"
              >
                Clear Cart
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default CartPage;
